 export const TASA_IVA = 0.13;

+// RF-002: la tasa por defecto es 13 %; TASA_IVA del entorno (número entre 0 y 1) la reemplaza.
+// Un valor presente pero inválido es un error: no se cae en silencio al 13 %.
+export function tasaIva(env = process.env) {
+  const crudo = env.TASA_IVA;
+  if (crudo === undefined) return TASA_IVA;
+  const valor = Number(crudo);
+  if (!/^(?:\d+(?:\.\d+)?|\.\d+)$/.test(crudo) || !(valor >= 0 && valor <= 1))
+    throw new RangeError(`TASA_IVA inválida: ${JSON.stringify(crudo)} (debe ser un número entre 0 y 1)`);
+  return valor;
+}
